# Total bars in the dev window.
DEV_BARS = 1440


def parse_schedule(text):
    """Parse DEV_SCHEDULE into a dict {fill_bar: [(side, k), ...]}."""
    out = {}
    if not text:
        return out
    for tok in text.split(","):
        tok = tok.strip()
        if not tok:
            continue
        side = "buy" if "B" in tok else "sell"
        bar_s, k_s = tok.replace("B", " ").replace("S", " ").split()
        out.setdefault(int(bar_s), []).append((side, int(k_s)))
    return out
